import{_ as o}from"./chunks/02.DKb5XHsw.js";import{_ as e,o as a,c as n,aa as r}from"./chunks/framework.BAs_AphD.js";const s="/buildary-help-preview/academy/img/novy-ukol/02.webp",l="/buildary-help-preview/academy/img/novy-ukol/08.webp",i="/buildary-help-preview/academy/img/novy-ukol/09.webp",k="/buildary-help-preview/academy/img/novy-ukol/15.webp",d="/buildary-help-preview/media/cs/tickets/ukol_souvisejici_ukol.png",v="/buildary-help-preview/media/cs/tickets/souvisejici_ukoly.png",j=JSON.parse('{"title":"Zadat úkol","description":"","frontmatter":{"title":"Zadat úkol","wiki":"cs:tickets:task_new"},"headers":[],"relativePath":"tickets/task_new.md","filePath":"tickets/task_new.md","lastUpdated":1794209661000}'),u={name:"tickets/task_new.md"};function p(m,t,g,h,z,y){return a(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="zadat-ukol" tabindex="-1">Zadat úkol <a class="header-anchor" href="#zadat-ukol" aria-label="Permalink to &quot;Zadat úkol&quot;">​</a></h1><p>Úkol zadáte formulářem <strong>Nový úkol</strong>: popíšete, co je potřeba udělat, určíte termín a místo na výkresu nebo v mapě a přiřadíte Řešitele a Schvalovatele. Úkol můžete založit i z kopie jiného úkolu, ze záznamu ve stavebním deníku nebo jako související úkol.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/novy-ukol">Zadat vadu nebo úkol do výkresu</a> a <a href="/buildary-help-preview/akademie/ukol-k-zaznamu">Založit úkol k zápisu v deníku</a> v Akademii.</p><h2 id="kde-ukol-zalozit" tabindex="-1">Kde úkol založit <a class="header-anchor" href="#kde-ukol-zalozit" aria-label="Permalink to &quot;Kde úkol založit&quot;">​</a></h2><p>Nejčastěji klikněte v <strong>Seznamu úkolů</strong> nebo v <strong>Kanbanu úkolů</strong> na <strong>Nový úkol</strong>. Formulář otevřete i jinými cestami a podle toho se některá pole předvyplní:</p><table tabindex="0"><thead><tr><th>Kde</th><th>Co se předvyplní</th></tr></thead><tbody><tr><td><strong>Nový úkol</strong> v Seznamu úkolů nebo v Kanbanu</td><td>plánovaný termín, stav <strong>Nezahájeno</strong></td></tr><tr><td>tlačítko <strong>+</strong> v záhlaví sloupce Kanbanu</td><td>stav podle sloupce – viz <a href="/buildary-help-preview/tickets/task_grid#kanban">Seznam úkolů a filtry</a></td></tr><tr><td>dvojklik do výkresu nebo mapy na stránce <strong>Výkresy a Mapa</strong></td><td>značka ve výkresu nebo poloha v mapě – viz <a href="/buildary-help-preview/tickets/task_drawings">Výkresy a mapa</a></td></tr><tr><td><strong>Kopíruj poslední úkol</strong> ve formuláři Nový úkol</td><td>údaje z naposledy zadaného úkolu – viz <a href="#zkopirovat-ukol">Zkopírovat úkol</a></td></tr><tr><td><strong>Vytvoření kopie úkolu</strong> v detailu úkolu</td><td>téměř všechny údaje kopírovaného úkolu</td></tr><tr><td><strong>Vytvořit související úkol</strong> v detailu úkolu</td><td>vazba na původní úkol – viz <a href="#souvisejici-ukol">Související úkol</a></td></tr><tr><td>záznam ve stavebním deníku</td><td>vazba na záznam – viz <a href="#ukol-ze-zaznamu-v-deniku">Úkol ze záznamu v deníku</a></td></tr></tbody></table><p>Je-li tlačítko <strong>Nový úkol</strong> zašedlé, nemáte oprávnění zakládat úkoly – viz <a href="/buildary-help-preview/tickets/permissions">Kdo co smí v úkolech</a>. V mobilní aplikaci zadáte úkol i z fotografie – viz <a href="/buildary-help-preview/tickets/m_task_new">Nový úkol v mobilu</a>.</p><h2 id="formular-novy-ukol" tabindex="-1">Formulář Nový úkol <a class="header-anchor" href="#formular-novy-ukol" aria-label="Permalink to &quot;Formulář Nový úkol&quot;">​</a></h2><figure class="shot" style="--w:760px;"><img src="'+s+'" alt="Horní část formuláře Nový úkol s poli Předmět, Popis, Kategorie, Stav, Priorita, Štítky a termíny" loading="lazy"></figure><table tabindex="0"><thead><tr><th>Pole</th><th>Co do něj patří</th></tr></thead><tbody><tr><td><strong>Předmět</strong></td><td>Krátký a výstižný název úkolu. Zobrazuje se v seznamu, v Kanbanu i na výkresu. Můžete ho nadiktovat tlačítkem <strong>Nadiktovat</strong>.</td></tr><tr><td><strong>Popis</strong></td><td>Podrobné zadání, například rozsah vady nebo požadovaný postup. Také ho můžete nadiktovat.</td></tr><tr><td><strong>Kategorie</strong></td><td>Druh úkolu, například <strong>Neshody, vady a nedodělky</strong> nebo <strong>Kontroly a zkoušky</strong>. Seznam kategorií spravuje administrátor stavby – viz <a href="/buildary-help-preview/tickets/rules">Kategorie, štítky a pravidla</a>.</td></tr><tr><td><strong>Stav</strong></td><td>Při zakládání vybíráte z <strong>Koncept</strong>, <strong>Nezahájeno</strong>, <strong>Probíhá</strong> a <strong>Čeká se</strong>. Předvyplní se <strong>Nezahájeno</strong>. Význam stavů popisuje <a href="/buildary-help-preview/tickets/task_edit#stavy-ukolu">Řešit a schválit úkol</a>.</td></tr><tr><td><strong>Priorita</strong></td><td><strong>Nízká</strong>, <strong>Střední</strong> nebo <strong>Vysoká</strong>.</td></tr><tr><td><strong>Štítky</strong></td><td>Vlastní označení úkolů, pokud je administrátor pro stavbu nastavil.</td></tr><tr><td><strong>Plánovaný termín</strong></td><td><strong>Plánovaný začátek</strong> je předvyplněný dnešním datem, <strong>Plánovaný konec</strong> o týden později. Obě data můžete změnit. Podle plánovaného konce se úkol řadí mezi aktuální a zpožděné.</td></tr><tr><td><strong>Skutečný termín</strong></td><td>Ve formuláři ho nevyplňujete, <strong>Skutečný začátek</strong> a <strong>Skutečný konec</strong> doplní aplikace sama.</td></tr></tbody></table><p>Další části formuláře – <strong>Umístění a výkresy</strong>, <strong>Přílohy</strong> a <strong>Přiřazení řešitele a schvalovatele</strong> – jsou popsané níže. Úkol uložíte tlačítkem <strong>Uložit</strong>, <strong>Zrušit</strong> formulář zavře bez uložení.</p><h3 id="umisteni-na-vykresu-a-v-mape" tabindex="-1">Umístění na výkresu a v mapě <a class="header-anchor" href="#umisteni-na-vykresu-a-v-mape" aria-label="Permalink to &quot;Umístění na výkresu a v mapě&quot;">​</a></h3><p>Část <strong>Umístění a výkresy</strong> je sbalená. V záhlaví vidíte souhrn – část stavby, adresu a GPS. Kliknutím na šipku ji rozbalíte.</p><figure class="shot" style="--w:760px;"><img src="'+l+'" alt="Rozbalená část Umístění a výkresy s vybranou částí stavby, výkresem a mapou" loading="lazy"></figure><ul><li><strong>Část stavby</strong> – vyberte část, které se úkol týká.</li><li><strong>Výkres</strong> – po výběru části se zobrazí její výchozí výkres. Jiný vyberete tlačítkem <strong>Vyber výkres</strong>, případně <strong>Změň výkres</strong>. Ikonou koše výkres od úkolu odeberete.</li><li><strong>Zadej značky</strong> – otevře okno <strong>Značky</strong> s výkresem. Zvolte nástroj značka, klikněte na místo ve výkresu a potvrďte <strong>OK</strong>. Do jednoho výkresu můžete vložit více značek, jejich počet se ukáže v rohu náhledu.</li><li><strong>Umístění na mapě</strong> – klikněte do mapy na místo stavby, nebo vyplňte <strong>Místo stavby</strong> (adresu). Pole <strong>GPS Souřadnice</strong> ukazuje polohu značky.</li></ul><figure class="shot" style="--w:760px;"><img src="'+i+'" alt="Okno Značky s výkresem, nástroji pro zvětšení, posun a značku a tlačítky Zrušit a OK" loading="lazy"></figure><p>Výkresy se do úkolů nenahrávají – nejdřív je musí administrátor nahrát k části stavby, viz <a href="/buildary-help-preview/diary/projectparts">Části stavby a výkresy</a>. Úkoly umístěné na výkresech a v mapě pak najdete na stránce <strong>Výkresy a Mapa</strong> – viz <a href="/buildary-help-preview/tickets/task_drawings">Výkresy a mapa</a>.</p><h3 id="prilohy" tabindex="-1">Přílohy <a class="header-anchor" href="#prilohy" aria-label="Permalink to &quot;Přílohy&quot;">​</a></h3><p>V části <strong>Přílohy</strong> přidejte fotografie, dokumenty a další soubory: přetáhněte je do vyznačeného pole, nebo klikněte na <strong>Nahrát přílohu</strong>.</p><h3 id="resitele-a-schvalovatele" tabindex="-1">Řešitelé a Schvalovatelé <a class="header-anchor" href="#resitele-a-schvalovatele" aria-label="Permalink to &quot;Řešitelé a Schvalovatelé&quot;">​</a></h3><p>V části <strong>Přiřazení řešitele a schvalovatele</strong> začněte psát jméno a vyberte osobu ze seznamu. Do obou polí můžete vybrat více osob.</p><figure class="shot" style="--w:760px;"><img src="'+k+'" alt="Části Přílohy a Přiřazení řešitele a schvalovatele s vybranými osobami a tlačítky Zrušit a Uložit" loading="lazy"></figure><ul><li><strong>Řešitelé</strong> úkol plní a mění jeho stav.</li><li><strong>Schvalovatelé</strong> úkol po dokončení kontrolují.</li></ul><p>Vybírat můžete jen členy projektového týmu stavby. Chybí-li vám v seznamu někdo, musí ho administrátor nejdřív přidat do týmu – viz <a href="/buildary-help-preview/diary/projectteam">Projektový tým: firmy a lidé</a>.</p><p>Pokud má stavba nastavená <strong>pravidla</strong> pro Řešitele a Schvalovatele, pole se vyplní automaticky podle kategorie, části stavby nebo výkresu úkolu. Předvyplněné osoby můžete změnit nebo doplnit. Jak pravidla nastavit, popisuje <a href="/buildary-help-preview/tickets/rules">Kategorie, štítky a pravidla</a>.</p><h2 id="zkopirovat-ukol" tabindex="-1">Zkopírovat úkol <a class="header-anchor" href="#zkopirovat-ukol" aria-label="Permalink to &quot;Zkopírovat úkol&quot;">​</a></h2><p>Podobné úkoly nemusíte vyplňovat znovu:</p><table tabindex="0"><thead><tr><th>Volba</th><th>Kde ji najdete</th><th>Co se zkopíruje</th></tr></thead><tbody><tr><td><strong>Kopíruj poslední úkol</strong></td><td>vpravo nahoře ve formuláři <strong>Nový úkol</strong></td><td>z naposledy zadaného úkolu předmět, kategorie, výkres (bez značek), místo stavby, Řešitelé a Schvalovatelé</td></tr><tr><td><strong>Vytvoření kopie úkolu</strong></td><td>v detailu úkolu v menu <strong>⋮</strong></td><td>všechno kromě stavu a štítků – včetně značek ve výkresu a polohy v mapě, příloh a termínů</td></tr></tbody></table><p>Zkopírované údaje ve formuláři před uložením upravte podle potřeby.</p><h2 id="souvisejici-ukol" tabindex="-1">Související úkol <a class="header-anchor" href="#souvisejici-ukol" aria-label="Permalink to &quot;Související úkol&quot;">​</a></h2><p>Když z jednoho úkolu vyplývá další, založte ho jako související. Úkoly zůstanou propojené a z jednoho se snadno dostanete na druhý.</p><p>V detailu původního úkolu otevřete menu <strong>⋮</strong> a zvolte <strong>Vytvořit související úkol</strong>. Otevře se formulář <strong>Nový úkol</strong> s vazbou na původní úkol. Vazbu můžete na konci formuláře zrušit.</p><figure class="shot" style="--w:760px;"><img src="'+d+'" alt="Menu v detailu úkolu s volbou Vytvořit související úkol" loading="lazy"></figure><p>Související úkoly najdete v detailu úkolu u <strong>Související položky</strong> – viz <a href="/buildary-help-preview/tickets/task_edit#souvisejici-polozky">Řešit a schválit úkol</a> – a v Seznamu úkolů ve sloupci <strong>Související úkoly</strong>:</p><figure class="shot" style="--w:600px;"><img src="'+v+'" alt="Sloupec Související úkoly v seznamu s modrou ikonou u úkolu ze záznamu v deníku a oranžovými ikonami s počtem souvisejících úkolů" loading="lazy"></figure><ul><li><strong>Modrá ikona</strong> – úkol je propojený se záznamem ve stavebním deníku. Kliknutím otevřete deník na dni, kde záznam je.</li><li><strong>Oranžová ikona s číslem</strong> – úkol má související úkoly, číslo udává jejich počet. Kliknutím otevřete jejich seznam a z něj přejdete na detail souvisejícího úkolu.</li></ul><p>Sloupec přidáte do seznamu volbou <strong>Výběr sloupců</strong> – viz <a href="/buildary-help-preview/tickets/taskviews#vybrat-sloupce">Přizpůsobit pohledy</a>.</p><h2 id="ukol-ze-zaznamu-v-deniku" tabindex="-1">Úkol ze záznamu v deníku <a class="header-anchor" href="#ukol-ze-zaznamu-v-deniku" aria-label="Permalink to &quot;Úkol ze záznamu v deníku&quot;">​</a></h2><p>Ze záznamu stavebního deníku založíte úkol tlačítkem <strong>Vytvoř nový úkol pro tento záznam</strong> v záhlaví provedené práce, nebo volbou <strong>Vytvořit nový úkol pro tento záznam</strong> v <strong>Dalších volbách</strong> Dalšího záznamu. Ve formuláři <strong>Nový úkol</strong> pak vidíte, ke kterému záznamu se úkol váže, a úkol zůstane se záznamem propojený. Modul Management úkolů musí být na stavbě zapnutý.</p><figure class="shot" style="--w:760px;"><img src="'+o+'" alt="Formulář Nový úkol propojený se záznamem z deníku" loading="lazy"></figure><p>Postup popisuje <a href="/buildary-help-preview/diary/dailyentriesothers#ukol-k-zaznamu">Další záznamy</a>. V mobilní aplikaci viz <a href="/buildary-help-preview/tickets/m_task_new#ukol-ze-zaznamu-v-deniku">Nový úkol v mobilu</a>.</p>',41)])])}const f=e(u,[["render",p]]);export{j as __pageData,f as default};
